insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('model-grade1-math-20','MATH.G1.ADD.WITHIN20_01.L1','MATH.G1.ADD.WITHIN20_01','build','independent',array['grade1','grade2','grade3']::text[],'{"en":"Pack 3 rows of apples with 4 in each row."}'::jsonb,'{"en":"Count one row, then add rows one at a time and watch the total climb by the same amount each time."}'::jsonb,'{"en":"3 rows of 4 is 4 + 4 + 4 = 12. Adding the same number again and again is what multiplying will mean."}'::jsonb,'3,4','[]'::jsonb,'{"activityType":"array-builder","contextTags":["nature"],"estimatedMinutes":2,"grade":"grade1","level":1,"subject":"math","options":[],"engine":{"kind":"array-builder","rows":3,"columns":4,"emoji":"🍎","maxRows":6,"maxColumns":7}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('model-grade1-math-21','MATH.G1.ADD.WITHIN20_01.L2','MATH.G1.ADD.WITHIN20_01','build','independent',array['grade1','grade2','grade3']::text[],'{"en":"Fill 4 rows of the egg tray with 5 in each row."}'::jsonb,'{"en":"Count one row, then add rows one at a time and watch the total climb by the same amount each time."}'::jsonb,'{"en":"4 rows of 5 is 5 + 5 + 5 + 5 = 20. Adding the same number again and again is what multiplying will mean."}'::jsonb,'4,5','[]'::jsonb,'{"activityType":"array-builder","contextTags":["animals"],"estimatedMinutes":2,"grade":"grade1","level":2,"subject":"math","options":[],"engine":{"kind":"array-builder","rows":4,"columns":5,"emoji":"🥚","maxRows":6,"maxColumns":7}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('model-grade1-math-22','MATH.G1.ADD.WITHIN20_01.L3','MATH.G1.ADD.WITHIN20_01','build','independent',array['grade1','grade2','grade3']::text[],'{"en":"Arrange 5 rows of pots with 3 in each row."}'::jsonb,'{"en":"Count one row, then add rows one at a time and watch the total climb by the same amount each time."}'::jsonb,'{"en":"5 rows of 3 is 3 + 3 + 3 + 3 + 3 = 15. Adding the same number again and again is what multiplying will mean."}'::jsonb,'5,3','[]'::jsonb,'{"activityType":"array-builder","contextTags":["nature"],"estimatedMinutes":2,"grade":"grade1","level":3,"subject":"math","options":[],"engine":{"kind":"array-builder","rows":5,"columns":3,"emoji":"🪴","maxRows":6,"maxColumns":7}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('model-grade1-math-23','MATH.G1.ADD.WITHIN20_01.L3','MATH.G1.ADD.WITHIN20_01','build','independent',array['grade1','grade2','grade3']::text[],'{"en":"Set out 2 rows of cakes with 6 in each row."}'::jsonb,'{"en":"Count one row, then add rows one at a time and watch the total climb by the same amount each time."}'::jsonb,'{"en":"2 rows of 6 is 6 + 6 = 12. Adding the same number again and again is what multiplying will mean."}'::jsonb,'2,6','[]'::jsonb,'{"activityType":"array-builder","contextTags":["stories"],"estimatedMinutes":2,"grade":"grade1","level":3,"subject":"math","options":[],"engine":{"kind":"array-builder","rows":2,"columns":6,"emoji":"🧁","maxRows":6,"maxColumns":7}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-0','SCI.PK.PHYS.SINK_FLOAT_01.L1','SCI.PK.PHYS.SINK_FLOAT_01','predict','guided',array['kindergarten']::text[],'{"en":"Pip is about to put this cork gently into the water. What do you predict?"}'::jsonb,'{"en":"Think about how heavy it felt for its size, and about all those tiny air pockets."}'::jsonb,'{"en":"The cork floats. It is light for its size — less dense than water — partly because of the air trapped inside it."}'::jsonb,'float','[]'::jsonb,'{"activityType":"investigation","contextTags":["nature"],"estimatedMinutes":3,"grade":"prek","level":1,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🟤💧","clues":[{"id":"c0","label":"Pick it up","detail":"The cork feels very light for its size."},{"id":"c1","label":"Squeeze it","detail":"It is springy, and full of tiny air pockets you can just see."},{"id":"c2","label":"Look at the water","detail":"The bowl is deep enough for the cork to go right under, if it would."}],"outcomes":[{"id":"float","label":"It will float","emoji":"🛟"},{"id":"sink","label":"It will sink","emoji":"⬇️"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-1','SCI.PK.PHYS.SINK_FLOAT_01.L2','SCI.PK.PHYS.SINK_FLOAT_01','predict','independent',array['kindergarten']::text[],'{"en":"Now the small stone is going into the same water. What do you predict?"}'::jsonb,'{"en":"Size is not what decided it last time. Think about heavy-for-its-size instead."}'::jsonb,'{"en":"The stone sinks. It is heavy for its size — denser than water — and being smaller than the cork made no difference at all."}'::jsonb,'sink','[]'::jsonb,'{"activityType":"investigation","contextTags":["nature"],"estimatedMinutes":3,"grade":"prek","level":2,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🪨💧","clues":[{"id":"c0","label":"Pick it up","detail":"The stone is small, but it feels heavy in your hand."},{"id":"c1","label":"Look closely","detail":"It is solid all the way through. No air pockets anywhere."},{"id":"c2","label":"Remember the cork","detail":"The cork was bigger than this stone, and it floated."}],"outcomes":[{"id":"float","label":"It will float","emoji":"🛟"},{"id":"sink","label":"It will sink","emoji":"⬇️"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-2','SCI.PK.EARTH.WEATHER_01.L2','SCI.PK.EARTH.WEATHER_01','predict','independent',array['kindergarten']::text[],'{"en":"Nova looks out of the window before going outside. What weather do you predict?"}'::jsonb,'{"en":"You cannot see air. You can see what it does to things that are light enough to move."}'::jsonb,'{"en":"Windy. Air is invisible, so we read the wind from what it moves — a flag, branches, a hat. The bright sky told us it was not rain or snow."}'::jsonb,'windy','[]'::jsonb,'{"activityType":"investigation","contextTags":["nature"],"estimatedMinutes":3,"grade":"prek","level":2,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🪟🚩","clues":[{"id":"c0","label":"Look at the flag","detail":"The flag is stretched out straight and snapping about."},{"id":"c1","label":"Look at the trees","detail":"The branches are bending all one way, then springing back."},{"id":"c2","label":"Look at the sky","detail":"The sky is bright. No dark clouds, and nothing is falling."}],"outcomes":[{"id":"windy","label":"Windy","emoji":"💨"},{"id":"rainy","label":"Rainy","emoji":"🌧️"},{"id":"snowy","label":"Snowy","emoji":"🌨️"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-3','SCI.PK.LIFE.HABITAT_01.L3','SCI.PK.LIFE.HABITAT_01','predict','independent',array['prek','kindergarten']::text[],'{"en":"This animal needs a home. Where do you predict it lives?"}'::jsonb,'{"en":"Every clue points at the same thing this animal cannot do without."}'::jsonb,'{"en":"A freshwater pond. Webbed feet for swimming, damp skin that must not dry out, and shell-less eggs that need water — a habitat has to supply what an animal needs."}'::jsonb,'pond','[]'::jsonb,'{"activityType":"investigation","contextTags":["animals","nature"],"estimatedMinutes":3,"grade":"prek","level":3,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🐸","clues":[{"id":"c0","label":"Look at its feet","detail":"The back feet are wide and webbed, like little paddles."},{"id":"c1","label":"Look at its skin","detail":"The skin is damp and smooth. It dries out quickly in the sun."},{"id":"c2","label":"Ask about its babies","detail":"Its eggs are soft jelly with no shell, so they must stay wet."}],"outcomes":[{"id":"pond","label":"A freshwater pond","emoji":"🪷"},{"id":"desert","label":"A hot dry desert","emoji":"🏜️"},{"id":"ocean","label":"The salty ocean","emoji":"🌊"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-0','SCI.G1.PHYS.MAGNET_01.L1','SCI.G1.PHYS.MAGNET_01','predict','guided',array['grade1','grade2','grade3']::text[],'{"en":"Pip holds a magnet near this paper clip. What do you predict?"}'::jsonb,'{"en":"Magnets are picky about materials, not about shape or colour. What is this one made of?"}'::jsonb,'{"en":"It is attracted. Magnets attract iron, and steel is mostly iron. A thin plastic coating does not stop it."}'::jsonb,'attract','[]'::jsonb,'{"activityType":"investigation","contextTags":["building","puzzles"],"estimatedMinutes":3,"grade":"grade1","level":1,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🧲📎","clues":[{"id":"c0","label":"What is it made of?","detail":"The clip is steel. Steel is mostly iron."},{"id":"c1","label":"Test another clip","detail":"A second steel clip jumped to the magnet straight away."},{"id":"c2","label":"Check the coating","detail":"It has a thin plastic coating, but the steel is right underneath."}],"outcomes":[{"id":"attract","label":"The magnet will attract it","emoji":"🧲"},{"id":"ignore","label":"The magnet will not attract it","emoji":"🚫"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-1','SCI.G1.PHYS.MAGNET_01.L2','SCI.G1.PHYS.MAGNET_01','predict','independent',array['grade1','grade2','grade3']::text[],'{"en":"Now the magnet goes near a piece of aluminium foil. What do you predict?"}'::jsonb,'{"en":"The clue that mattered last time was not shiny, and was not metal. It was more specific than that."}'::jsonb,'{"en":"Not attracted. This is the useful surprise: shiny and metal are not enough. An everyday magnet pulls on iron, and aluminium has none."}'::jsonb,'ignore','[]'::jsonb,'{"activityType":"investigation","contextTags":["building","puzzles"],"estimatedMinutes":3,"grade":"grade1","level":2,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🧲◻️","clues":[{"id":"c0","label":"What is it made of?","detail":"Aluminium. It is a metal, and it is shiny like the clip was."},{"id":"c1","label":"Is there any iron?","detail":"No iron in it at all. Aluminium is its own metal."},{"id":"c2","label":"Try a wooden block","detail":"Wood is not a metal, and the magnet ignored it completely."}],"outcomes":[{"id":"attract","label":"The magnet will attract it","emoji":"🧲"},{"id":"ignore","label":"The magnet will not attract it","emoji":"🚫"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-2','SCI.G1.PHYS.FORCE_01.L2','SCI.G1.PHYS.FORCE_01','predict','independent',array['grade1','grade2','grade3']::text[],'{"en":"The same toy car is sent down the ramp, but a rug has been put at the bottom. What do you predict?"}'::jsonb,'{"en":"Think about what your hand felt on each surface, and what that would do to a rolling wheel."}'::jsonb,'{"en":"It stops sooner. The rough rug means more friction, and friction is a force that slows things down. Changing only one thing is what made this a fair test."}'::jsonb,'sooner','[]'::jsonb,'{"activityType":"investigation","contextTags":["building"],"estimatedMinutes":3,"grade":"grade1","level":2,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🏎️🟫","clues":[{"id":"c0","label":"Feel the rug","detail":"Rough and fluffy. Your hand drags when you push it along."},{"id":"c1","label":"Feel the floor","detail":"The bare floor is smooth. Your hand slides easily."},{"id":"c2","label":"Keep it fair","detail":"Same car, same ramp, same starting place. Only the surface changed."}],"outcomes":[{"id":"sooner","label":"It will stop sooner","emoji":"🛑"},{"id":"farther","label":"It will roll farther","emoji":"➡️"},{"id":"same","label":"It will go exactly as far","emoji":"🟰"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-3','SCI.G1.EARTH.SPACE_01.L3','SCI.G1.EARTH.SPACE_01','predict','independent',array['grade1','grade2','grade3']::text[],'{"en":"It is dark outside the window and the Moon is up. What do you predict is happening to the Sun?"}'::jsonb,'{"en":"The globe clue is the one that explains why morning always comes back."}'::jsonb,'{"en":"Earth has turned. The Sun has not gone anywhere — our side of the planet has spun into its own shadow, which is why night ends without anyone relighting it."}'::jsonb,'turned','[]'::jsonb,'{"activityType":"investigation","contextTags":["space"],"estimatedMinutes":3,"grade":"grade1","level":3,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🌙🪟","clues":[{"id":"c0","label":"Look at the Moon","detail":"The Moon is bright, but it gives no warmth at all."},{"id":"c1","label":"Think about morning","detail":"Every morning the Sun comes back on the same side of the sky."},{"id":"c2","label":"Spin a globe","detail":"Turn the globe once and your country goes from light into shadow."}],"outcomes":[{"id":"turned","label":"Our side of Earth has turned away from the Sun","emoji":"🌍"},{"id":"gone","label":"The Sun has gone out for the night","emoji":"🕯️"},{"id":"moved","label":"The Sun has moved to a different sky","emoji":"🚀"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-4','SCI.PK.LIFE.NEEDS_01.L2','SCI.PK.LIFE.NEEDS_01','predict','independent',array['kindergarten']::text[],'{"en":"This healthy green plant is going into a closed dark cupboard for two weeks. What do you predict?"}'::jsonb,'{"en":"Water was not the thing being taken away. What else do those leaves need every day?"}'::jsonb,'{"en":"It grows pale and weak. Water alone is not enough — green leaves need light to make their own food, so the cupboard removes the one thing water cannot replace."}'::jsonb,'weak','[]'::jsonb,'{"activityType":"investigation","contextTags":["nature"],"estimatedMinutes":3,"grade":"prek","level":2,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🪴🚪","clues":[{"id":"c0","label":"Look at the leaves","detail":"Green, wide and open — turned towards wherever the light is."},{"id":"c1","label":"Ask what plants eat","detail":"Nobody feeds a plant. Green leaves make food using light."},{"id":"c2","label":"Check the cupboard","detail":"It will still be watered. There is simply no light in there at all."}],"outcomes":[{"id":"weak","label":"It will grow pale and weak","emoji":"🥀"},{"id":"fine","label":"It will be perfectly fine","emoji":"🌿"},{"id":"faster","label":"It will grow faster","emoji":"⬆️"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-5','SCI.PK.EARTH.WEATHER_01.L3','SCI.PK.EARTH.WEATHER_01','predict','independent',array['kindergarten']::text[],'{"en":"A puddle sits on the path on a warm sunny day. What do you predict by evening?"}'::jsonb,'{"en":"It cannot run away anywhere. So where could water go that you would not be able to see?"}'::jsonb,'{"en":"It gets smaller. The water becomes invisible water vapour in the air — that is evaporation, and it happens quietly in the warmth without anything boiling."}'::jsonb,'smaller','[]'::jsonb,'{"activityType":"investigation","contextTags":["nature"],"estimatedMinutes":3,"grade":"prek","level":3,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"💧☀️","clues":[{"id":"c0","label":"Touch the path","detail":"The path around the puddle is warm and completely dry."},{"id":"c1","label":"Check yesterday","detail":"There was a puddle here yesterday too, and by teatime it had gone."},{"id":"c2","label":"Look for a drain","detail":"No drain, no slope. The water has nowhere to run away to."}],"outcomes":[{"id":"smaller","label":"The puddle will get smaller","emoji":"🔽"},{"id":"bigger","label":"The puddle will get bigger","emoji":"🔼"},{"id":"same","label":"It will stay exactly the same","emoji":"🟰"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-4','SCI.G1.PHYS.MATTER_01.L1','SCI.G1.PHYS.MATTER_01','predict','guided',array['grade1','grade2','grade3']::text[],'{"en":"An ice cube is put on a plate in a warm room. What do you predict happens to how much water there is?"}'::jsonb,'{"en":"Two clues are about what stayed the same. Only the shape is really changing."}'::jsonb,'{"en":"The same water. Melting changes a solid into a liquid, but the water itself is unchanged — same stuff, same amount, different state."}'::jsonb,'same','[]'::jsonb,'{"activityType":"investigation","contextTags":["building"],"estimatedMinutes":3,"grade":"grade1","level":1,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🧊🍽️","clues":[{"id":"c0","label":"Feel the room","detail":"The room is warm. The ice is already glistening and wet."},{"id":"c1","label":"Weigh it","detail":"The ice cube weighs the same as the puddle it left last time."},{"id":"c2","label":"Taste test","detail":"The melted puddle was still plain water. Nothing else got in."}],"outcomes":[{"id":"same","label":"The same water, in a new shape","emoji":"💧"},{"id":"less","label":"Less water than before","emoji":"🔽"},{"id":"new","label":"It turns into a different substance","emoji":"✨"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-5','SCI.G1.PHYS.FORCE_01.L3','SCI.G1.PHYS.FORCE_01','predict','independent',array['grade1','grade2','grade3']::text[],'{"en":"Nova has a rope tied to a sledge and is moving backwards, rope taut. What kind of force is she using?"}'::jsonb,'{"en":"Is the sledge moving away from her, or coming towards her?"}'::jsonb,'{"en":"A pull. A pull brings something towards you and a push sends it away — a taut rope can only ever pull, which is why nobody pushes with string."}'::jsonb,'pull','[]'::jsonb,'{"activityType":"investigation","contextTags":["building"],"estimatedMinutes":3,"grade":"grade1","level":3,"subject":"science","options":[],"engine":{"kind":"investigation","scene":"🛷🧶","clues":[{"id":"c0","label":"Watch the rope","detail":"The rope is stretched tight between Nova and the sledge."},{"id":"c1","label":"Watch her feet","detail":"She is stepping backwards, away from the sledge."},{"id":"c2","label":"Watch the sledge","detail":"The sledge follows her, moving towards her the whole time."}],"outcomes":[{"id":"pull","label":"A pull","emoji":"🪢"},{"id":"push","label":"A push","emoji":"🤲"},{"id":"neither","label":"No force at all","emoji":"🚫"}]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-6','SCI.PK.LIFE.LIVING_01.L1','SCI.PK.LIFE.LIVING_01','sort','guided',array['prek','kindergarten']::text[],'{"en":"Sort these into living things and things that were never alive."}'::jsonb,'{"en":"Ask of each one: does it need food or water, does it grow, could it have babies?"}'::jsonb,'{"en":"Living things grow, need food and water, and can make more of themselves. A stone does none of those, however real and solid it is."}'::jsonb,'{"cat":"living","oak":"living","stone":"never","spoon":"never","beetle":"living","cup":"never"}','[]'::jsonb,'{"activityType":"sorting","contextTags":["nature","animals"],"estimatedMinutes":3,"grade":"prek","level":1,"subject":"science","options":[],"engine":{"kind":"sorting","items":[{"id":"cat","label":"Cat","emoji":"🐈"},{"id":"oak","label":"Oak tree","emoji":"🌳"},{"id":"stone","label":"Stone","emoji":"🪨"},{"id":"spoon","label":"Spoon","emoji":"🥄"},{"id":"beetle","label":"Beetle","emoji":"🐞"},{"id":"cup","label":"Cup","emoji":"🥤"}],"bins":[{"id":"living","label":"Living","emoji":"🌱"},{"id":"never","label":"Never alive","emoji":"🪨"}],"solution":{"cat":"living","oak":"living","stone":"never","spoon":"never","beetle":"living","cup":"never"}}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-7','SCI.PK.SENSE.FIVE_01.L2','SCI.PK.SENSE.FIVE_01','sort','independent',array['prek','kindergarten']::text[],'{"en":"Which sense would notice each of these best? Sort them."}'::jsonb,'{"en":"Picture yourself in the room with each one. Which part of you notices it first?"}'::jsonb,'{"en":"Eyes use light, ears catch sounds travelling through the air, and skin feels texture and temperature. Often more than one sense helps at once."}'::jsonb,'{"rainbow":"eyes","thunder":"ears","fur":"hands","bell":"ears","ice":"hands","star":"eyes"}','[]'::jsonb,'{"activityType":"sorting","contextTags":["nature"],"estimatedMinutes":3,"grade":"prek","level":2,"subject":"science","options":[],"engine":{"kind":"sorting","items":[{"id":"rainbow","label":"A rainbow","emoji":"🌈"},{"id":"thunder","label":"Thunder","emoji":"⛈️"},{"id":"fur","label":"Soft fur","emoji":"🧶"},{"id":"bell","label":"A ringing bell","emoji":"🔔"},{"id":"ice","label":"A cold ice cube","emoji":"🧊"},{"id":"star","label":"A tiny far star","emoji":"⭐"}],"bins":[{"id":"eyes","label":"Eyes","emoji":"👀"},{"id":"ears","label":"Ears","emoji":"👂"},{"id":"hands","label":"Hands","emoji":"✋"}],"solution":{"rainbow":"eyes","thunder":"ears","fur":"hands","bell":"ears","ice":"hands","star":"eyes"}}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-6','SCI.G1.PHYS.MATTER_01.L1','SCI.G1.PHYS.MATTER_01','sort','guided',array['grade1','grade2','grade3']::text[],'{"en":"Sort each one by whether it is a solid or a liquid."}'::jsonb,'{"en":"Imagine pouring each one into a differently shaped jar. Which ones would change shape to fit?"}'::jsonb,'{"en":"A liquid takes the shape of its container; a solid keeps its own shape. Honey is slow, but pour it into a round jar and it still becomes round."}'::jsonb,'{"milk":"liquid","brick":"solid","juice":"liquid","key":"solid","honey":"liquid","book":"solid"}','[]'::jsonb,'{"activityType":"sorting","contextTags":["building"],"estimatedMinutes":3,"grade":"grade1","level":1,"subject":"science","options":[],"engine":{"kind":"sorting","items":[{"id":"milk","label":"Milk","emoji":"🥛"},{"id":"brick","label":"Brick","emoji":"🧱"},{"id":"juice","label":"Juice","emoji":"🧃"},{"id":"key","label":"Key","emoji":"🔑"},{"id":"honey","label":"Honey","emoji":"🍯"},{"id":"book","label":"Book","emoji":"📕"}],"bins":[{"id":"solid","label":"Solid","emoji":"🧱"},{"id":"liquid","label":"Liquid","emoji":"💧"}],"solution":{"milk":"liquid","brick":"solid","juice":"liquid","key":"solid","honey":"liquid","book":"solid"}}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-7','SCI.G1.PHYS.LIGHT_01.L2','SCI.G1.PHYS.LIGHT_01','sort','independent',array['grade1','grade2','grade3']::text[],'{"en":"A torch shines at each material. Sort them by how much light gets through."}'::jsonb,'{"en":"Think about whether you could read a word held behind each one."}'::jsonb,'{"en":"Transparent materials let light through clearly, translucent ones let it through scattered, and opaque ones stop it — which is exactly when you get a shadow."}'::jsonb,'{"window":"clear","tracing":"blurry","card":"blocked","water":"clear","door":"blocked","curtain":"blurry"}','[]'::jsonb,'{"activityType":"sorting","contextTags":["building","puzzles"],"estimatedMinutes":3,"grade":"grade1","level":2,"subject":"science","options":[],"engine":{"kind":"sorting","items":[{"id":"window","label":"Glass window","emoji":"🪟"},{"id":"tracing","label":"Tracing paper","emoji":"📃"},{"id":"card","label":"Thick cardboard","emoji":"📦"},{"id":"water","label":"A glass of clear water","emoji":"🥛"},{"id":"door","label":"Wooden door","emoji":"🚪"},{"id":"curtain","label":"Thin curtain","emoji":"🪟"}],"bins":[{"id":"clear","label":"See through it","emoji":"🪟"},{"id":"blurry","label":"Light but blurry","emoji":"📃"},{"id":"blocked","label":"Blocks the light","emoji":"📦"}],"solution":{"window":"clear","tracing":"blurry","card":"blocked","water":"clear","door":"blocked","curtain":"blurry"}}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-8','SCI.G1.EARTH.SEASONS_01.L3','SCI.G1.EARTH.SEASONS_01','sort','independent',array['grade1','grade2','grade3']::text[],'{"en":"Sort each change by the season it belongs to."}'::jsonb,'{"en":"Two of these are about getting ready for cold, and two are about things starting again."}'::jsonb,'{"en":"Seasons come around in order, and living things follow them: growing and hatching in spring, storing and shedding in autumn, waiting out the cold in winter."}'::jsonb,'{"buds":"spring","leaves":"autumn","frost":"winter","chicks":"spring","acorns":"autumn","bare":"winter"}','[]'::jsonb,'{"activityType":"sorting","contextTags":["nature","animals"],"estimatedMinutes":3,"grade":"grade1","level":3,"subject":"science","options":[],"engine":{"kind":"sorting","items":[{"id":"buds","label":"Buds opening on bare branches","emoji":"🌷"},{"id":"leaves","label":"Leaves turning gold and falling","emoji":"🍂"},{"id":"frost","label":"Frost on the window in the morning","emoji":"❄️"},{"id":"chicks","label":"Eggs hatching in a nest","emoji":"🐣"},{"id":"acorns","label":"Squirrels burying acorns","emoji":"🌰"},{"id":"bare","label":"Bare branches and the shortest days","emoji":"🌑"}],"bins":[{"id":"spring","label":"Spring","emoji":"🌷"},{"id":"autumn","label":"Autumn","emoji":"🍂"},{"id":"winter","label":"Winter","emoji":"❄️"}],"solution":{"buds":"spring","leaves":"autumn","frost":"winter","chicks":"spring","acorns":"autumn","bare":"winter"}}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-prek-science-8','SCI.PK.LIFE.HABITAT_01.L3','SCI.PK.LIFE.HABITAT_01','sort','independent',array['prek','kindergarten']::text[],'{"en":"Give each animal a home where it can find what it needs."}'::jsonb,'{"en":"For each animal ask the same three questions: where is its food, its water, and somewhere safe to shelter?"}'::jsonb,'{"en":"A habitat is not just scenery — it is the place that supplies an animal''s food, water and shelter. Move the whale to the forest and none of the three are there."}'::jsonb,'{"whale":"ocean","squirrel":"forest","camel":"desert","octopus":"ocean","owl":"forest","lizard":"desert"}','[]'::jsonb,'{"activityType":"sorting","contextTags":["animals","nature"],"estimatedMinutes":3,"grade":"prek","level":3,"subject":"science","options":[],"engine":{"kind":"sorting","items":[{"id":"whale","label":"Whale","emoji":"🐳"},{"id":"squirrel","label":"Squirrel","emoji":"🐿️"},{"id":"camel","label":"Camel","emoji":"🐪"},{"id":"octopus","label":"Octopus","emoji":"🐙"},{"id":"owl","label":"Owl","emoji":"🦉"},{"id":"lizard","label":"Desert lizard","emoji":"🦎"}],"bins":[{"id":"ocean","label":"Salty ocean","emoji":"🌊"},{"id":"forest","label":"Forest","emoji":"🌳"},{"id":"desert","label":"Hot desert","emoji":"🏜️"}],"solution":{"whale":"ocean","squirrel":"forest","camel":"desert","octopus":"ocean","owl":"forest","lizard":"desert"}}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-9','SCI.G1.EARTH.SPACE_01.L2','SCI.G1.EARTH.SPACE_01','sort','independent',array['grade1','grade2','grade3']::text[],'{"en":"Sort what you would see in the sky by when you would see it."}'::jsonb,'{"en":"The stars are always there. Think about what has to be missing before you can see them."}'::jsonb,'{"en":"Day and night come from Earth turning, not from things switching on and off. The stars never leave — daylight is simply too bright for us to pick them out."}'::jsonb,'{"sun":"day","stars":"night","blue":"day","fullmoon":"night","shadows":"day","dark":"night"}','[]'::jsonb,'{"activityType":"sorting","contextTags":["space"],"estimatedMinutes":3,"grade":"grade1","level":2,"subject":"science","options":[],"engine":{"kind":"sorting","items":[{"id":"sun","label":"The Sun, high and bright","emoji":"☀️"},{"id":"stars","label":"Thousands of stars","emoji":"✨"},{"id":"blue","label":"A blue sky","emoji":"🟦"},{"id":"fullmoon","label":"The Moon at its brightest","emoji":"🌕"},{"id":"shadows","label":"Short sharp shadows on the ground","emoji":"🌳"},{"id":"dark","label":"Darkness you need a lamp to see in","emoji":"🔦"}],"bins":[{"id":"day","label":"Daytime","emoji":"☀️"},{"id":"night","label":"Night-time","emoji":"🌙"}],"solution":{"sun":"day","stars":"night","blue":"day","fullmoon":"night","shadows":"day","dark":"night"}}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-10','SCI.G1.LIFE.LIFECYCLE_01.L1','SCI.G1.LIFE.LIFECYCLE_01','sequence','guided',array['grade1','grade2','grade3']::text[],'{"en":"Put the butterfly''s life in order, from first to last."}'::jsonb,'{"en":"Start with the smallest and stillest. The eating comes before the changing."}'::jsonb,'{"en":"Egg, caterpillar, chrysalis, butterfly. The caterpillar eats to store what it needs for the change ahead — the still stage is not resting, it is rebuilding."}'::jsonb,'["s0","s1","s2","s3"]','[]'::jsonb,'{"activityType":"ordering","contextTags":["animals","nature"],"estimatedMinutes":3,"grade":"grade1","level":1,"subject":"science","options":[],"engine":{"kind":"ordering","items":[{"id":"s2","label":"Chrysalis hanging still","emoji":"🛡️"},{"id":"s3","label":"Butterfly flying","emoji":"🦋"},{"id":"s0","label":"Egg on a leaf","emoji":"🥚"},{"id":"s1","label":"Caterpillar eating","emoji":"🐛"}],"solution":["s0","s1","s2","s3"]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-11','SCI.G1.LIFE.LIFECYCLE_01.L2','SCI.G1.LIFE.LIFECYCLE_01','sequence','independent',array['grade1','grade2','grade3']::text[],'{"en":"Put the sunflower''s life in order, from first to last."}'::jsonb,'{"en":"What has to be underground before anything can appear above it?"}'::jsonb,'{"en":"Seed, shoot, stem, flower — and the flower makes seeds, so the cycle begins again. That is why it is called a cycle and not a line."}'::jsonb,'["s0","s1","s2","s3"]','[]'::jsonb,'{"activityType":"ordering","contextTags":["nature"],"estimatedMinutes":3,"grade":"grade1","level":2,"subject":"science","options":[],"engine":{"kind":"ordering","items":[{"id":"s2","label":"Tall stem and leaves","emoji":"🪴"},{"id":"s3","label":"Flower full of new seeds","emoji":"🌻"},{"id":"s0","label":"Seed in the soil","emoji":"🌰"},{"id":"s1","label":"First shoot and roots","emoji":"🌱"}],"solution":["s0","s1","s2","s3"]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
insert into content.items(id,lesson_id,skill_id,verb,phase,bands,prompt,hint,explanation,answer,assets,delivery,review_status,source) values('lab-grade1-science-12','SCI.G1.LIFE.LIFECYCLE_01.L3','SCI.G1.LIFE.LIFECYCLE_01','sequence','independent',array['grade1','grade2','grade3']::text[],'{"en":"Put the frog''s life in order, from first to last."}'::jsonb,'{"en":"Think about when it can breathe underwater, and when it needs to reach the air."}'::jsonb,'{"en":"Eggs, tadpole, legs, frog. It starts life able to live only in water and ends able to leave it — which is why the eggs had to be laid in a pond."}'::jsonb,'["s0","s1","s2","s3"]','[]'::jsonb,'{"activityType":"ordering","contextTags":["animals","nature"],"estimatedMinutes":3,"grade":"grade1","level":3,"subject":"science","options":[],"engine":{"kind":"ordering","items":[{"id":"s2","label":"Back legs growing","emoji":"🦵"},{"id":"s3","label":"Young frog leaving the water","emoji":"🐸"},{"id":"s0","label":"Jelly eggs in the pond","emoji":"🫧"},{"id":"s1","label":"Tadpole with a tail","emoji":"🐟"}],"solution":["s0","s1","s2","s3"]}}'::jsonb,'published','generated') on conflict(id) do update set lesson_id=excluded.lesson_id,skill_id=excluded.skill_id,verb=excluded.verb,phase=excluded.phase,bands=excluded.bands,prompt=excluded.prompt,hint=excluded.hint,explanation=excluded.explanation,answer=excluded.answer,delivery=excluded.delivery,review_status=excluded.review_status;
