-- WP-05: the bundled catalogue, migrated into `content.*`.
--
-- Generated by `node scripts/build-content-catalogue.mjs`. Do not hand-edit: change
-- the generator, or make the change in the studio, which is the point of the package.
--
-- 78 skills, 523 items. Existing content is seeded
-- `published` because it is what children are being served today; seeding it `draft`
-- would empty the product on migration day. Distractor reasons come from the WP-04
-- inference and are flagged `reviewed = false`, which is the studio's work queue.
begin;

-- Skills (§C4 `Skill`). `child_name` is a mechanical placeholder for every row here;
-- naming a skill in Nova's voice is authoring, and the studio flags the ones still
-- carrying the generated form.

-- Lessons (§C4 `Lesson`). The bundled bank has no lesson layer; these are the
-- difficulty rungs it already encodes, made into rows an author can split and name.
-- `model` is null everywhere: nobody has written the worked example yet, and a
-- generated one would be a placeholder pretending to be teaching.

-- Items (§C4 `Item`), with their wrong answers and the reason each one is wrong.

-- The first published version, assembled from what was just seeded.
--
-- Publishing here rather than leaving it to a person means the app switches to the
-- database catalogue the moment this migration runs, instead of silently falling back
-- to the bundle until someone notices and presses a button.
do $$ declare document jsonb; v integer; begin
  document := content.cq_snapshot(true);
  if jsonb_array_length(document->'items') = 0 then
    raise exception 'Seed produced no published items';
  end if;
  v := nextval(pg_get_serial_sequence('content.catalogue_versions','version'));
  document := jsonb_set(document, '{version}', to_jsonb(v));
  document := jsonb_set(document, '{label}', to_jsonb('migrated from the bundle'::text));
  update content.catalogue_versions set is_current = false where is_current;
  overriding system value
  values (v, 'migrated from the bundle', document, jsonb_array_length(document->'items'),
    jsonb_array_length(document->'skills'), jsonb_array_length(document->'lessons'),
    'Seeded from lib/curriculum.ts and lib/skill-graph.ts by scripts/build-content-catalogue.mjs.', true);
end $$;

update private.backend_metadata set version = '202609200005';
commit;
